-- payout 收款账户与余额解释（S1）· mor_platform 注册块 147 · 休眠写入。目标库 mor_platform；未执行（阶段 4 生成，主会话审阅后执行）。
-- 块号 147：任务卡原写 146，但 146 已被 tax（requirements/20261029/tax-结账算税与事件登记）占用、145 = REQ-04、144 = 联合查询，本稿取 147；阶段 6 只读核对现网最大块号后替换（ID 区间 900000000000147001—900000000000147999）。
-- 依据：requirements/20261030/payout-收款账户与余额解释/technique.md 第 8.3—8.6、9 节；结构清单见同目录 db/platform-support/dml.sql。
-- 内容：
--   A 权限 8（ACTIVE）：Client 3（CLIENT_PAYOUT_ACCOUNT_READ / _MANAGE、CLIENT_BALANCE_READ），Operations 5（PAYOUT_BENEFICIARY_*）。
--   B 授权（休眠 REVOKED）：平台管理员角色 900000000000000510 × 5 个 Operations 权限；Client 系统角色按租户回填——每个已开通
--     （owner_status <> PENDING）CLIENT 工作区的 TENANT_OWNER / TENANT_ADMIN 得 3 个、TENANT_DEVELOPER / TENANT_VIEWER 得
--     CLIENT_PAYOUT_ACCOUNT_READ 与 CLIENT_BALANCE_READ（technique 8.6 的 OWNER / ADMIN / MEMBER 映射到现有四个系统角色，
--     MEMBER = 开发者与只读成员）。Client 角色按租户创建、没有固定 role_id，故用 INSERT … SELECT，主键取高位区间
--     9100000000000000000 起递增（与 client-console-团队成员与邀请 db/dml.sql 相同写法）。首次 ACTIVE 投影的新工作区由
--     ClientTeamPermissions 矩阵直接授予 ACTIVE（Platform 新版本部署后生效）。
--   C 菜单与按钮（DISABLED，仅 OPERATIONS）：财务 900000000000097301 下「出款」组 + 收款账户核验、Owner 账户与余额两页 + 4 个按钮。
--     Client 门户导航不读 t_console_resource（Client 权限由 client-console-bff 判断），故不建 Client「资金」菜单资源。
--   D Gateway 路由（DISABLED）：Client 7 条 /api/client/payout/v1/** → client-console-bff /client-payout/v1/**（CLIENT_JWT + HUMAN_AUTHENTICATED，
--     形状照块 138 Client 路由）；Operations 12 条 /api/operations/payout-admin/v1/** → operations-console-bff /payout-admin/v1/**（OPERATIONS_JWT +
--     HUMAN_PERMISSION，形状照块 143）。Client 目标按 target_service_code = client-console-bff 取得，不存在时失败关闭。
--   E 通知模板 4 个 × zh-CN / en（ACTIVE，不经快照，无条件写入）；模板路由到 SES_PRIMARY，仅该发送账号存在时写入 4 行，否则跳过；参数 bankName、accountLast4、currency、
--     availableAt（仅 VERIFIED）、reasonText（其余三个），不含户名或账号原值。调用方白名单 notification.http.callers.payout-service
--     由部署配置开启（application.yml 默认仍为空）。
-- 行数：permission 8 / admin role_permission 5 / console_resource 7 / gateway_route 19（Client 7、Operations 12）/ route_header 71 / query_param 19 / guard_rule 114 / notification_template 4 / template_content 8 / notification_route 4，固定行合计 259；另加 Client 系统角色授权（每个已开通 CLIENT 工作区 10 行）。
-- 重复执行被主键 / 唯一键拒绝（ERROR 1062，事务内首条即失败、不留半成品）。执行前跑 -precheck.sql；之后跑 -verify.sql。
-- Gateway 快照编译 DISABLED 行：执行前用候选 Platform JAR 的生产编译器离线编译。
-- =====================================================================================================================
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';

SET @b147_time = UTC_TIMESTAMP(6);
SET @b147_actor_id = 1;
-- 既有对象：Client BFF 目标各环境 ID 不同，先取到变量；它或管理员角色、财务菜单、Operations 目标缺失时下一句的标量子查询返回两行 →
-- ERROR 1242 中止，事务未开始。SES_PRIMARY 发送账号不是前置条件（见 E 段）。
SET @b147_client_target = (SELECT target_id FROM t_gateway_target WHERE target_service_code = 'client-console-bff' AND channel = 'CLIENT');
SET @b147_lookup_guard = (SELECT 1 UNION ALL SELECT 1 FROM DUAL WHERE @b147_client_target IS NULL
  OR NOT EXISTS (SELECT 1 FROM t_role WHERE role_id = 900000000000000510) OR NOT EXISTS (SELECT 1 FROM t_console_resource WHERE resource_id = 900000000000097301)
  OR NOT EXISTS (SELECT 1 FROM t_gateway_target WHERE target_id = 900000000000000001));

START TRANSACTION;

-- A. 权限

-- B1. 平台管理员授权（休眠）

-- B2. Client 系统角色授权（休眠；按已开通 CLIENT 工作区回填）
SET @b147_rp_base = (SELECT COALESCE(MAX(role_permission_id), 9099999999999999999)
  FROM t_role_permission WHERE role_permission_id >= 9100000000000000000);

SELECT @b147_rp_base + ROW_NUMBER() OVER (ORDER BY r.role_id, m.permission_id), r.role_id, m.permission_id,
  'REVOKED', 1, @b147_time, @b147_time
FROM t_role r
JOIN t_access_tenant t ON t.tenant_id = r.tenant_id
JOIN (
  SELECT 'TENANT_OWNER' role_code, 900000000000147101 permission_id
  UNION ALL SELECT 'TENANT_OWNER', 900000000000147102
  UNION ALL SELECT 'TENANT_OWNER', 900000000000147103
  UNION ALL SELECT 'TENANT_ADMIN', 900000000000147101
  UNION ALL SELECT 'TENANT_ADMIN', 900000000000147102
  UNION ALL SELECT 'TENANT_ADMIN', 900000000000147103
  UNION ALL SELECT 'TENANT_DEVELOPER', 900000000000147101
  UNION ALL SELECT 'TENANT_DEVELOPER', 900000000000147103
  UNION ALL SELECT 'TENANT_VIEWER', 900000000000147101
  UNION ALL SELECT 'TENANT_VIEWER', 900000000000147103
) m ON m.role_code = r.role_code
JOIN t_permission p ON p.permission_id = m.permission_id AND p.status = 'ACTIVE'
WHERE r.tenant_scope = 'TENANT' AND r.system_role = 1 AND r.scope_key = CAST(t.tenant_id AS CHAR)
  AND t.tenant_type = 'CLIENT' AND t.owner_status <> 'PENDING'
  AND NOT EXISTS (SELECT 1 FROM t_role_permission x WHERE x.role_id = r.role_id AND x.permission_id = m.permission_id);

