    1, @b147_time, @b147_time),
  (900000000000147812, 900000000000147801, 'en', 'PAYTECH · Payout account verified',
    CONCAT('Payout account verified', CHAR(10), CHAR(10), 'Your payout account has been verified:', CHAR(10), 'Bank: ${bankName}', CHAR(10), 'Account ending: ${accountLast4}', CHAR(10), 'Currency: ${currency}', CHAR(10), CHAR(10), 'It can be used for withdrawals from ${availableAt}.', CHAR(10), 'If you did not request this, contact us immediately.'),
