-- 模板路由只在 SES_PRIMARY 发送账号存在时写入；不存在（如本机）时跳过，verify 显示 0 行，待配置账号后再补路由。
SET @b147_ses_primary = (SELECT provider_id FROM t_notification_provider WHERE provider_code = 'SES_PRIMARY');
  ROW(900000000000147821, 900000000000147801, @b147_ses_primary, NULL, 'ACTIVE', 1, @b147_time, @b147_time),
  ROW(900000000000147822, 900000000000147802, @b147_ses_primary, NULL, 'ACTIVE', 1, @b147_time, @b147_time),
  ROW(900000000000147823, 900000000000147803, @b147_ses_primary, NULL, 'ACTIVE', 1, @b147_time, @b147_time),
  ROW(900000000000147824, 900000000000147804, @b147_ses_primary, NULL, 'ACTIVE', 1, @b147_time, @b147_time)) AS b147_routes WHERE @b147_ses_primary IS NOT NULL;

-- 预期：A 8、B1 5、B2 = 已开通 CLIENT 工作区系统角色 × 矩阵（每工作区 10）、C 7、
